footer="\n## \u9650\u5236\u4e0e\u505c\u6b62\u4f4d\u7f6e\n\n\u4e0a\u8ff0\u5747\u4e3afold0\u3001seed1\u3001\u6700\u591a1 epoch\u7684\u5b9e\u73b0\u9a8c\u6536\uff0c\u4e0d\u4ee5\u8fd9\u4e9bF1/loss\u9009\u578b\uff0c\u4e5f\u4e0d\u636e\u6b64\u58f0\u79f0\u5206\u7c7b\u63d0\u5347\u3001\u6cdb\u5316\u6216\u5b8c\u6574\u8bad\u7ec3\u7a33\u5b9a\u3002\u5f53\u524dSTATIC245\u7ef4\uff0cS4\u8f7d\u4f53760\u7ef4\u4fdd\u6301\u539f\u6837\u3002\u539f\u540d\u4e3b\u5b9e\u9a8c\u4ecd\u9700\u539f\u540dS0\u914d\u5bf9\u57fa\u7ebf\uff0c\u65e7\u533f\u540d8H\u6210\u7ee9\u53ea\u80fd\u4f5c\u5386\u53f2\u53c2\u8003\u3002\n\n\u6700\u7ec8\u5b9e\u9a8c\u5c06\u6309\u7528\u6237\u5b89\u6392\u5728\u663e\u5b58\u5145\u8db3\u7684\u670d\u52a1\u5668\u8fd0\u884c\uff1bRTX3050 4GiB\u9650\u5236\u4ec5\u6765\u81ea\u5f53\u524d\u672c\u673a\u5f00\u53d1\u73af\u5883\u3002\u672c\u8f6e\u6ca1\u6709\u90e8\u7f72\u6216\u6d4b\u91cf\u670d\u52a1\u5668\u3002\u6b63\u5f0f\u5168\u5c3a\u5bf8\u8d44\u6e90\u4ecd\u9700\u5728\u76ee\u6807\u670d\u52a1\u5668\u5b9e\u6d4b\uff1b\u82e5\u5408\u7ea6\u63a2\u9488OOM\uff0c\u5fc5\u987b\u4f5c\u4e3a\u4e0b\u4e00\u9636\u6bb5\u8d44\u6e90\u524d\u63d0\u4fdd\u7559\uff0c\u4e0d\u80fd\u636e\u6b64\u7f29\u51cf\u6700\u7ec8\u65b9\u6848\u3002\n\n\u6ca1\u6709\u65b0\u589e\u5173\u7cfb\u3001\u91cd\u7f16\u7801\u3001\u4e0b\u8f7d\u4f9d\u8d56\u3001\u4fee\u6539\u539fHGT/tokenizer/\u8bad\u7ec3\u5668\u6216\u91cd\u5199\u65e7\u5b9e\u9a8c\u3002\u4ea7\u7269\u4fdd\u7559\u5728WSL\u5de5\u4f5c\u6811\uff0c\u4e0d\u53e6\u884c\u590d\u5236\u81f3C\u76d8\u3002\u672c\u8f6e\u6309\u5171\u4eab\u4e0a\u4e0b\u6587\u672c\u5730\u63d0\u4ea4\uff0c\u4e0d\u81ea\u52a8\u63a8\u9001\uff0c\u4e0d\u63a8\u8fdbNS-P5\u3002\n"
commands="\n## \u5b9e\u9645\u547d\u4ee4\n\n```bash\n# mando\uff0cCPU\u65f6 CUDA_VISIBLE_DEVICES=''\uff1b\u5176\u4f59\u6cbf\u7528OMP/MKL=2\u548c\u539fTREE_SITTER_LIB_DIR\npython -B -m scripts.node_sem.p4b_acceptance prepare\n# \u9996\u6b21\u65e5\u5fd7\u63a5\u5165\u5931\u8d25\u540e\u7684\u660e\u786e\u6279\u51c6\u6062\u590d\uff1b\u4ee5\u4e0b\u76ee\u5f55\u5df2\u7ecf\u5b58\u5728\uff0c\u7981\u6b62\u8986\u76d6\u91cd\u8dd1\npython -B -m scripts.node_sem.p4b_acceptance resume-prepare --out scripts/node_sem/artifacts/ns_p4/attempt3/resume1\npython -B -m scripts.node_sem.p4b_acceptance run --only cpu_reentrancy_node_S3 --out scripts/node_sem/artifacts/ns_p4/attempt3/resume1\n# CPU\u5176\u4f59S3m/S4/S4g/S4m/S4-noG\uff1bGPU\u4f7f\u7528gpu_<task_id>_<name>\uff0c\u786e\u5207\u547d\u4ee4\u89c1controller.json\npython -B -m scripts.node_sem.p4b_parity_diagnostic\npython -B -m scripts.node_sem.p4b_acceptance precision-resume-prepare --out scripts/node_sem/artifacts/ns_p4/attempt3/resume2\npython -B -m scripts.node_sem.p4b_acceptance verify --out scripts/node_sem/artifacts/ns_p4/attempt3/resume2\nCUDA_VISIBLE_DEVICES='' python -B -m pytest -q -p no:cacheprovider scripts/node_sem/tests\nCUDA_VISIBLE_DEVICES='' python -B -m pytest -q -p no:cacheprovider scripts/DFG/dfg_v2/tests\nCUDA_VISIBLE_DEVICES='' python -B -m pytest -q -p no:cacheprovider scripts/DFG/tests tests/test_graph_utils.py\n```\n\n\u547d\u4ee4\u7528\u4e8e\u8bf4\u660e\u5df2\u6267\u884c\u8fc7\u7a0b\uff1b\u8fd0\u884c\u5165\u53e3\u62d2\u7edd\u540c\u4e00\u8eab\u4efd\u518d\u6b21\u542f\u52a8\u3002\u6bcf\u9879\u5b8c\u6574\u547d\u4ee4\u3001\u9000\u51fa\u7801\u548c\u5899\u949f\u8017\u65f6\u5728cpu_controller.json/gpu_controller.json\u4e2d\uff0c\u5931\u8d25\u73b0\u573a\u548c\u4fee\u590d\u524d\u6d4b\u8bd5\u53e6\u5b58\u3002\n"
cpu=[];gpu=[];parity=[];rows=[]
for job in plan['jobs']:
 identity='_'.join((job['actual_device'],job['task_id'],job['name']))
 jobroot=Path(plan.get('reused',{}).get(identity,{}).get('root',str(OUT)))
 folder=jobroot/'runs'/job['actual_device']/job['task_id']/job['name']
 acceptance=read(folder/'acceptance.json') if (folder/'acceptance.json').exists() else None
 if job['actual_device']=='cpu':
  assert acceptance is not None
  cpu.append('| {} | {} | {:.6f} | {:.6f} | {:.2f} | {:.2f} |'.format(job['name'],job['parameters'],acceptance['history'][0]['train_loss'],acceptance['history'][0]['inner_val_loss'],acceptance['constructor_seconds'],acceptance['fit_seconds']))
 else:
  resource=jobroot/'resources'/job['task_id']/job['name']
  c=read(resource/'comparison.json')
  controller=next(r for r in read(jobroot/'gpu_controller.json') if r['job']==identity)
  r=dict(task_id=job['task_id'],name=job['name'],profile=job['profile'],passed=acceptance is not None,parameters=job['parameters'],
   seconds=controller['seconds'],fit_seconds=acceptance['fit_seconds'] if acceptance else None,
   reserved_ratio=c['reserved_ratio'],significant_memory_increase=c['significant_memory_increase'])
  r.update(c['current']);r.update({'delta_'+k:v for k,v in c['delta_mib'].items()})
  rows.append(r)
  gpu.append('| {} / {} | {} | {:.2f} | {:.0f} | {:.0f} | {:+.2f} | {:+.0f} | {:+.0f} | {:.3f} | {:.2f} |'.format(job['task_id'],job['name'],'PASS' if acceptance else 'OOM',r['peak_allocated_mib'],r['peak_reserved_mib'],r['minimum_free_mib'],r['delta_peak_allocated_mib'],r['delta_peak_reserved_mib'],r['delta_minimum_free_mib'],r['reserved_ratio'],r['seconds']))
  if (resource/'cpu_gpu_parity.json').exists():
   p=read(resource/'cpu_gpu_parity.json')
   parity.append('| {} | {:.9g} | {:.9g} | {:.9g} | {:.9g} | {} |'.format(job['name'],p['default_precision_comparison']['max_absolute'],p['max_absolute'],p['tensor_relative'],p['max_elementwise_relative'],p['passed']))
with (OUT/'resources_summary.csv').open('x',newline='',encoding='utf8') as stream:
 writer=csv.DictWriter(stream,fieldnames=list(rows[0]),lineterminator="\n");writer.writeheader();writer.writerows(rows)
